WITH parsed AS (SELECT id, customer_id, created_at, coupon_codes, items, COALESCE(ship_to.city, 'UNKNOWN') AS city_or_unknown, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, attributes['gift'] AS gift, FORALL(items, li -> li.qty <= 5) AS all_small_qty, SIZE(items) AS num_items FROM carts) SELECT CASE WHEN num_items >= 3 THEN 'PREMIUM' ELSE 'STANDARD' END AS num_items_tier, COUNT(DISTINCT id) AS distinct_ids, MAX(num_items) AS max_num_items FROM parsed GROUP BY 1 ORDER BY num_items_tier;
